<?php $e = static fn (mixed $v): string => App\Core\View::e($v); $csrf = App\Core\Security::csrfToken(); ?><section class="page-stack"><div class="section-heading"><div><p class="eyebrow">Governanca</p><h1>Organizacoes e projetos</h1><p class="muted">Estrutura para separar operacoes sem misturar campeonatos de entidades diferentes.</p></div></div><?php if (!empty($message)): ?><p class="success"><?= $e($message) ?></p><?php endif; ?><div class="dashboard-grid"><article class="panel"><h2>Nova organizacao</h2><form method="post" class="form-grid" action="<?= $e(App\Core\Config::url('/admin/governanca/organizacoes')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Nome <input name="name" required></label><label>Slug <input name="slug" pattern="[a-z0-9-]+" required></label><button type="submit">Criar organizacao</button></form></article><article class="panel"><h2>Novo projeto</h2><form method="post" class="form-grid" action="<?= $e(App\Core\Config::url('/admin/governanca/projetos')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Organizacao <select name="organization_id" required><option value="">Selecione</option><?php foreach ($organizations as $organization): ?><option value="<?= (int) $organization['id'] ?>"><?= $e($organization['name']) ?></option><?php endforeach; ?></select></label><label>Nome <input name="name" required></label><label>Slug <input name="slug" pattern="[a-z0-9-]+" required></label><button type="submit">Criar projeto</button></form></article></div><article class="panel"><h2>Projetos ativos</h2><div class="table-wrap"><table><thead><tr><th>Organizacao</th><th>Projeto</th><th>Status</th></tr></thead><tbody><?php foreach ($projects as $project): ?><tr><td><?= $e($project['organization_name']) ?></td><td><?= $e($project['name']) ?></td><td><?= $e($project['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></article></section>
